$lines = explode("\n", trim($data));
$addedCount = 0;

foreach ($lines as $line) {
    if (empty(trim($line))) continue;
    $cols = explode("\t", $line);
    
    // Check min cols
    if (count($cols) < 35) continue;
    
    $brandName = trim($cols[0]);
    $collection = trim($cols[2]);
    $categoryName = trim($cols[4]);
    $subCategoryName = trim($cols[5]);
    $name = trim($cols[6]);
    $sku = trim($cols[7]);
    
    $finish = trim($cols[10]);
    $size = trim($cols[19]) . 'x' . trim($cols[20]) . 'x' . trim($cols[21]) . 'mm';
    if ($size === "xxmm") {
        $size = "";
    }
    
    $mrp_str = trim($cols[22]);
    $price_str = trim($cols[26]);
    
    $mrp = (float) preg_replace('/[^\d.]/', '', $mrp_str);
    $price = (float) preg_replace('/[^\d.]/', '', $price_str);
    
    $desc = isset($cols[34]) ? trim($cols[34]) : '';
    $long_desc = isset($cols[35]) ? trim($cols[35]) : '';
    $meta_title = isset($cols[37]) ? trim($cols[37]) : '';
    $meta_desc = isset($cols[38]) ? trim($cols[38]) : '';
    
    $slug = Str::slug($name . ' ' . $sku);
    if (empty($sku)) {
        $sku = strtoupper($slug);
    }
    
    $cat = Category::firstOrCreate(['slug' => Str::slug($categoryName)], ['name' => $categoryName]);
    $brand = Brand::firstOrCreate(['slug' => Str::slug($brandName)], ['name' => $brandName]);
    $room = Room::firstOrCreate(['slug' => 'bathroom'], ['name' => 'Bathroom']);

    $product = Product::updateOrCreate(
        ['sku' => $sku],
        [
            'name' => $name,
            'slug' => $slug,
            'room_id' => $room->id,
            'category_id' => $cat->id,
            'brand_id' => $brand->id,
            'sub_category' => $subCategoryName,
            'collection' => $collection,
            'finish' => $finish,
            'size' => $size,
            'price_per_box' => $price,
            'price' => $price,
            'mrp' => $mrp,
            'short_description' => $desc,
            'description' => $long_desc,
            'seo_meta_title' => $meta_title,
            'seo_meta_description' => $meta_desc,
        ]
    );

    $imagePath = 'images/products/' . $slug . '.jpeg';
    
    ProductImage::updateOrCreate(
        ['product_id' => $product->id, 'image_path' => $imagePath],
        ['is_primary' => true]
    );
    
    $addedCount++;
}

echo "Successfully added $addedCount products from Sheet 6.\n";
